create table public.booking_quotes (id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,provider_id uuid not null references public.provider_profiles(id),status text not null default 'pending' check(status in ('pending','accepted','rejected','expired')),notes text,expires_at timestamptz,total_egp numeric(12,2) not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.quote_items (id uuid primary key default gen_random_uuid(),quote_id uuid not null references public.booking_quotes(id) on delete cascade,item_type text not null check(item_type in ('labour','material','fee')),description text not null,quantity numeric(10,2) not null check(quantity>0),unit_price_egp numeric(12,2) not null check(unit_price_egp>=0),created_at timestamptz not null default now());
create table public.change_orders (id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,provider_id uuid not null references public.provider_profiles(id),status text not null default 'pending' check(status in ('pending','approved','rejected')),reason text not null,total_egp numeric(12,2) not null check(total_egp>=0),decided_at timestamptz,created_at timestamptz not null default now());
create table public.change_order_items (id uuid primary key default gen_random_uuid(),change_order_id uuid not null references public.change_orders(id) on delete cascade,item_type text not null,description text not null,amount_egp numeric(12,2) not null check(amount_egp>=0));
create table public.payments (id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id),customer_id uuid not null references public.customer_profiles(id),provider_name text not null,status text not null default 'pending',amount_egp numeric(12,2) not null check(amount_egp>=0),currency char(3) not null default 'EGP',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payment_transactions (id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.payments(id) on delete cascade,provider_reference text,event_type text not null,amount_egp numeric(12,2) not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.refunds (id uuid primary key default gen_random_uuid(),payment_id uuid not null references public.payments(id),amount_egp numeric(12,2) not null check(amount_egp>0),status text not null default 'pending',reason text,created_at timestamptz not null default now());
create table public.provider_earnings (id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.provider_profiles(id),booking_id uuid not null references public.bookings(id),gross_egp numeric(12,2) not null,commission_egp numeric(12,2) not null,net_egp numeric(12,2) not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.provider_payouts (id uuid primary key default gen_random_uuid(),provider_id uuid not null references public.provider_profiles(id),amount_egp numeric(12,2) not null check(amount_egp>0),status text not null default 'requested',destination_snapshot jsonb not null default '{}',created_at timestamptz not null default now());
create table public.conversations (id uuid primary key default gen_random_uuid(),booking_id uuid references public.bookings(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.conversation_members (conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,last_read_at timestamptz,joined_at timestamptz not null default now(),primary key(conversation_id,user_id));
create table public.messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid references public.profiles(id),message_type text not null default 'text',body text,metadata jsonb not null default '{}',created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.message_attachments (id uuid primary key default gen_random_uuid(),message_id uuid not null references public.messages(id) on delete cascade,storage_path text not null,mime_type text,created_at timestamptz not null default now());
create table public.reviews (id uuid primary key default gen_random_uuid(),booking_id uuid not null unique references public.bookings(id),customer_id uuid not null references public.customer_profiles(id),provider_id uuid not null references public.provider_profiles(id),rating smallint not null check(rating between 1 and 5),comment text,is_anonymous boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table public.review_responses (id uuid primary key default gen_random_uuid(),review_id uuid not null unique references public.reviews(id) on delete cascade,provider_id uuid not null references public.provider_profiles(id),body text not null,created_at timestamptz not null default now());
create table public.favourites (customer_id uuid not null references public.customer_profiles(id) on delete cascade,provider_id uuid not null references public.provider_profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(customer_id,provider_id));
create table public.notifications (id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,type text not null,title text not null,body text not null,data jsonb not null default '{}',read_at timestamptz,created_at timestamptz not null default now());
create table public.notification_preferences (user_id uuid primary key references public.profiles(id) on delete cascade,push_enabled boolean not null default true,email_enabled boolean not null default true,sms_enabled boolean not null default false,updated_at timestamptz not null default now());
create table public.promo_codes (id uuid primary key default gen_random_uuid(),code text not null unique,discount_type text not null,discount_value numeric(12,2) not null,starts_at timestamptz,ends_at timestamptz,usage_limit integer,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.promo_code_uses (promo_code_id uuid not null references public.promo_codes(id),customer_id uuid not null references public.customer_profiles(id),booking_id uuid not null references public.bookings(id),used_at timestamptz not null default now(),primary key(promo_code_id,booking_id));
create table public.wallets (id uuid primary key default gen_random_uuid(),user_id uuid not null unique references public.profiles(id),balance_egp numeric(12,2) not null default 0 check(balance_egp>=0),updated_at timestamptz not null default now());
create table public.wallet_transactions (id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.wallets(id),amount_egp numeric(12,2) not null,type text not null,reference_type text,reference_id uuid,created_at timestamptz not null default now());
create table public.disputes (id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id),opened_by uuid not null references public.profiles(id),assigned_to uuid references public.profiles(id),reason text not null,status text not null default 'submitted',description text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.dispute_evidence (id uuid primary key default gen_random_uuid(),dispute_id uuid not null references public.disputes(id) on delete cascade,uploader_id uuid not null references public.profiles(id),storage_path text not null,created_at timestamptz not null default now());
create table public.support_tickets (id uuid primary key default gen_random_uuid(),requester_id uuid not null references public.profiles(id),assigned_to uuid references public.profiles(id),subject text not null,status text not null default 'open',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.support_messages (id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.support_tickets(id) on delete cascade,sender_id uuid not null references public.profiles(id),body text not null,created_at timestamptz not null default now());
create table public.user_reports (id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id),reported_user_id uuid references public.profiles(id),booking_id uuid references public.bookings(id),reason text not null,details text,created_at timestamptz not null default now());
create table public.admin_roles (id uuid primary key default gen_random_uuid(),name text not null unique,created_at timestamptz not null default now());
create table public.admin_permissions (role_id uuid not null references public.admin_roles(id) on delete cascade,permission text not null,primary key(role_id,permission));
create table public.admin_role_assignments (user_id uuid not null references public.profiles(id) on delete cascade,role_id uuid not null references public.admin_roles(id) on delete cascade,primary key(user_id,role_id));
create table public.audit_logs (id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity_type text not null,entity_id uuid,old_data jsonb,new_data jsonb,ip_hash text,created_at timestamptz not null default now());
create table public.app_settings (key text primary key,value jsonb not null,description text,updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());

create index messages_conversation_created_idx on public.messages(conversation_id,created_at desc) where deleted_at is null;
create index notifications_user_unread_idx on public.notifications(user_id,created_at desc) where read_at is null;
create index reviews_provider_created_idx on public.reviews(provider_id,created_at desc) where deleted_at is null;
create index disputes_assignee_status_idx on public.disputes(assigned_to,status);
